  function marketing(){return ctx.heading('CONTENT STUDIO','Ideas into impact.','Plan, draft and move your content forward.',`<div class="button-row"><button class="btn" data-page="assets">${icon('folder')}Media library</button>${ctx.addButton('posts','Create content')}</div>`)+ctx.toolbar(['All','Instagram','LinkedIn','X'])+`<div class="notice">Ask the assistant to create content and watch it fill the draft live. Publishing still needs your social account connections.</div>`+board('posts',ctx.records('posts'));}
