    if(detailTab==='Finance'){const invoices=linked('invoices'),expenses=linked('expenses'),outstanding=invoices.filter(x=>x.status==='Issued').reduce((n,x)=>n+Math.max(0,x.amount-(data().payments||[]).filter(p=>p.invoiceId===x.id).reduce((a,p)=>a+p.amount,0)),0);body=ctx.panel('Project invoices',`${ctx.currency(outstanding)} outstanding`,rows('invoices',invoices),add('invoices','Add invoice'))+ctx.panel('Project costs','Recorded expenses',rows('expenses',expenses),add('expenses','Add cost'));}
