  const fileDescriptions={'PROJECT.md':'Project brief, background, goals and scope.','INSTRUCTIONS.md':'How your assistant should work. Loaded on every request.','MEMORY.md':'Persistent facts and preferences. Your assistant can update this when you ask it to remember.','BRAND.md':'Your brand, colours, tone and content preferences.','DECISIONS.md':'Decisions worth keeping across conversations.'};
  function memory(){return ctx.heading('ASSISTANT PROJECT','A memory that stays with you.','Instructions, context and Markdown files that survive a new chat.')+`<div class="workspace-controls"><div class="field" style="min-width:240px"><label for="memory-scope">Workspace / project</label><select id="memory-scope" class="project-context" style="margin:0">${projectOptions(memoryScope,'VareonHQ · whole business')}</select></div><span class="sub">.md files · saved on this Mac · read by GPT and Codex</span></div><div class="memory-layout"><div class="memory-files"><div class="file-title">PROJECT FILES</div>${Object.keys(fileDescriptions).map(filename=>`<button class="${filename===memoryFile?'active':''}" data-memory-file="${filename}">${icon('file')} ${filename}</button>`).join('')}</div><div class="panel" style="padding:24px"><div class="memory-description"><strong>${memoryFile}</strong><br>${fileDescriptions[memoryFile]}</div><textarea class="memory-editor" id="memory-editor" aria-label="${memoryFile}">${esc(memoryRecord?.filename===memoryFile&&memoryRecord?.projectId===memoryScope?memoryRecord.content:'Loading your project file…')}</textarea><div class="button-row" style="justify-content:space-between;margin-top:16px"><span id="memory-save-state" class="sub">${memoryDirty?'Unsaved changes':'Persistent project context'}</span><button class="btn primary small" id="save-memory">Save Markdown file</button></div></div></div>`;}
  async function loadMemory(){try{const file=memoryFile,scope=memoryScope;const result=await api(`/memory?filename=${encodeURIComponent(file)}&projectId=${encodeURIComponent(scope)}`);if(file!==memoryFile||scope!==memoryScope||memoryDirty)return;memoryRecord=result;const editor=document.querySelector('#memory-editor');if(editor)editor.value=result.content;}catch(error){toast(error.message);}}
  function contextControls(){return `<div class="project-context"><label for="assistant-project">WORKING IN</label><select id="assistant-project" ${working?'disabled':''}>${projectOptions(projectId,'VareonHQ · whole business')}</select><div class="assistant-context-hint">Persistent memory + shared notes + your business records.</div></div>`;}
  const actionLabel=name=>({search_workspace:'Searching your workspace',get_prospect_followup_context:'Reading the prospect’s correspondence',get_prospect_followups:'Checking follow-up reminders',update_prospect_followup:'Updating the reminder',request_email_send:'Placing the draft in your review queue',open_editor:'Opening the editor',fill_editor:'Writing in the form',save_editor:'Saving to your board',move_card:'Moving a card',list_records:'Reading your workspace',read_memory_file:'Reading project memory',write_memory_file:'Remembering this',navigate_dashboard:'Opening a screen',save_notes:'Saving a note'}[name]||name.replaceAll('_',' '));
  function progressHTML(){return `<div id="assistant-progress">${working||actionLog.length?`<div class="assistant-activity">${actionLog.slice(-5).map(a=>`<div>${a.status==='Complete'?'✓':a.status==='Failed'?'!':'↗'} ${esc(actionLabel(a.name))}${a.status==='Failed'?` · ${esc(a.error||'Could not finish')}`:''}</div>`).join('')}${working?'<button class="text-btn" data-stop-assistant>Stop assistant</button>':''}</div>`:''}${streamText?`<div class="chat-message live-stream"><small>WORKING LIVE</small><div class="stream-content">${ctx.chatContent?ctx.chatContent(streamText):esc(streamText)}</div></div>`:''}</div>`;}
  function paintProgress(){const target=document.querySelector('#assistant-progress');if(target){const template=document.createElement('div');template.innerHTML=progressHTML();target.replaceWith(template.firstElementChild);document.querySelector('[data-stop-assistant]')?.addEventListener('click',()=>ctx.perform(()=>api('/assistant/stop',{method:'POST',body:'{}'})));}const scroll=document.querySelector('#chat-scroll');if(scroll&&working)scroll.scrollTop=scroll.scrollHeight;}
  async function takeOver(){if(!live)return;const draft={...live,record:{...live.record}};await api(`/editor/${draft.draftId}/take-over`,{method:'POST',body:'{}'});live=null;ctx.editor(draft.collection,draft.record);toast('The editor is yours. Assistant control stopped.');}
  function openLiveEditor(event){live={...event,record:{...event.record}};ctx.setPage(event.page);ctx.render();ctx.editor(event.collection,event.record);const overlay=document.querySelector('.modal-overlay'),form=document.querySelector('#record-form'),box=document.querySelector('.modal');overlay?.classList.add('ai-editor-overlay');box?.classList.add('live-form');box?.removeAttribute('aria-modal');box?.setAttribute('role','region');form?.setAttribute('data-live-draft',event.draftId);const banner=document.createElement('div');banner.className='live-banner';banner.innerHTML='<span class="dot"></span><span>Vareon is working in this form.<br>You’re watching the real draft as it is written.</span><button type="button" class="btn small" data-take-over style="margin-left:auto">Take over</button>';form?.prepend(banner);form?.querySelectorAll('input,textarea,select,button:not([data-take-over])').forEach(el=>el.disabled=true);const rich=form?.querySelector('[contenteditable]');if(rich)rich.contentEditable='false';banner.querySelector('[data-take-over]').onclick=()=>ctx.perform(takeOver);document.querySelector('#close-modal').onclick=()=>ctx.perform(takeOver);}
  function patchEditor(event){if(!live||event.draftId!==live.draftId)return;Object.assign(live.record,event.fields);if(live.collection==='emails')ctx.patchRichEditor?.(event.fields);if(live.collection==='posts'&&selectedPreview&&!selectedPreview.id){selectedPreview={...live.record};renderPreview();}for(const[key,value]of Object.entries(event.fields)){const input=document.querySelector(`#record-form [name="${CSS.escape(key)}"]`);if(!input)continue;if(input.type==='checkbox'){input.checked=!!value;continue;}input.value=key==='mediaIds'?JSON.stringify(value):Array.isArray(value)?value.join(key==='slides'?'\n---\n':key==='mediaUrls'?'\n':', '):key==='scheduledAt'||key==='nextRun'?ctx.datetimeInput(value):String(value??'');input.classList.add('live-field');if(input.tagName==='TEXTAREA')input.scrollTop=input.scrollHeight;} }
  async function handleEvent(event){
    const value=event.data;
    if(event.type.startsWith('assistant_')&&value.conversationId&&ctx.getConversationId?.()&&value.conversationId!==ctx.getConversationId())return;
    if(event.type==='assistant_started'){working=true;streamText='';actionLog=[];paintProgress();return;}
    if(event.type==='assistant_delta'){streamText+=value.delta;paintProgress();return;}
    if(event.type==='assistant_action'){const prior=actionLog.findLast(a=>a.name===value.name&&a.status==='Running');if(prior&&value.status!=='Running')Object.assign(prior,value);else actionLog.push(value);paintProgress();return;}
    if(event.type==='assistant_finished'){working=false;streamText='';paintProgress();return;}
    if(event.type!=='ui')return;
    if(value.action==='navigate'){ctx.setPage(value.page);ctx.render();}
    if(value.action==='open_editor'){if(document.querySelector('#record-form')&&!live){toast('Vareon prepared an editor while you were editing. Finish or close your form, then ask it to continue.');await api(`/editor/${value.draftId}/take-over`,{method:'POST',body:'{}'});return;}openLiveEditor(value);}
    if(value.action==='editor_patch')patchEditor(value);
    if(value.action==='editor_saved'){if(live?.draftId===value.draftId){live=null;ctx.closeModal();}highlight=value.id;ctx.setPage(value.page);await ctx.refresh();document.querySelector(`[data-card-id="${CSS.escape(value.id)}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});toast('Draft saved to your board');}
    if(['records_changed','card_moved'].includes(value.action)&&!dirty()){highlight=value.id||'';await ctx.refresh();}
    if(value.action==='memory_changed'&&ctx.getPage()==='memory'&&!memoryDirty)await loadMemory();
  }
