      box.innerHTML=`<div class="ticket-children-head"><strong>Child tickets</strong><span>${kids.length?`${done} of ${kids.length} done`:'None yet'}</span></div>${kids.length?`<div class="progress-track"><div class="progress-fill" style="width:${done/kids.length*100}%"></div></div><ul>${kids.map(k=>`<li><label class="ticket-check"><input type="checkbox" data-child-done="${esc(k.id)}" ${k.status==='Done'?'checked':''} ${isSoftware(projectOf(k))?'disabled title="Software tickets move through their workflow"':''} aria-label="Mark ${esc(k.title)} done"><span></span></label><button type="button" class="link" data-child-open="${esc(k.id)}">${k.ticketKey?`<small>${esc(k.ticketKey)}</small> `:''}${esc(k.title)}</button>${badge(k.status)}</li>`).join('')}</ul>`:''}<button type="button" class="btn small" id="add-child-ticket">${icon('plus')}Add child ticket</button><small class="ticket-children-note">Adding a child opens a new ticket; save this one first if you have unsaved changes.</small>`;
